    store: PreselectionPoolStore, artifacts: Sequence[dict]
) -> list[dict[str, Any]]:
    """Do not occupy a formal immutable key with a transient missing attempt."""
    results: list[dict[str, Any]] = []
    for artifact in artifacts:
